import Image from "next/image";
import { Download, QrCode } from "lucide-react";
import { siteConfig } from "@/lib/config";
import { Card } from "./parts";

const files = [
  { href: "/brand/qr-card.png", label: "Print card (PNG)" },
  { href: "/brand/qr-code.png", label: "QR code (PNG)" },
  { href: "/brand/qr-code.svg", label: "QR code (SVG, for printers)" },
];

/** Website QR code with download links (files are generated by scripts/generate-qr.mjs). */
export function QrCard() {
  return (
    <Card>
      <h2 className="flex items-center gap-2 font-extrabold text-navy">
        <QrCode className="size-5 text-gold" /> Website QR code
      </h2>
      <p className="mt-1 text-sm text-muted">Scanning opens {siteConfig.url.replace("https://", "")}. Use it on cards, flyers, vehicles and the showroom.</p>
      <div className="mx-auto mt-5 w-full max-w-[260px] overflow-hidden rounded-2xl border border-line">
        <Image src="/brand/qr-card.png" alt={`QR code for ${siteConfig.url}`} width={1200} height={1600} className="h-auto w-full" />
      </div>
      <ul className="mt-5 space-y-2">
        {files.map((f) => (
          <li key={f.href}>
            <a href={f.href} download className="flex items-center justify-between rounded-xl border border-line px-4 py-2.5 text-sm font-semibold hover:border-gold hover:text-gold-dark">
              {f.label}
              <Download className="size-4" />
            </a>
          </li>
        ))}
      </ul>
    </Card>
  );
}
